"""Runs the bundled GPT-Load gateway as a child process of the backend.

* Loopback only (HOST=127.0.0.1), on a dedicated port (default 31001) so it never collides with a
  GPT-Load the user installed themselves on 3001.
* Its data (database, auth.key, encryption.key) lives in <data_dir>/gateway.
* The management key is generated by us and kept in the OS credential store, never in a file we write.
* Off by default; once the user enables it, it starts with the app. Because it is a child of the
  backend (which the Tauri shell keeps in a kill-on-close Job Object) it dies with the app.
"""
import json
import os
import secrets as pysecrets
import socket
import subprocess
import sys
import threading
import time
import webbrowser
from pathlib import Path

import httpx

ADMIN_SECRET_ID = 'gateway-admin'
DEFAULT_PORT = 31001
PROVIDER_NAME = '本机网关（内置 GPT-Load）'


class GatewayError(Exception):
    """Message is safe to show to the user."""


def binary_name():
    return 'gpt-load.exe' if os.name == 'nt' else 'gpt-load'


def find_binary():
    override = os.environ.get('MAVOBOX_GATEWAY_BIN')
    candidates = [Path(override)] if override else []
    base = getattr(sys, '_MEIPASS', None)
    if base:
        candidates.append(Path(base) / 'gateway' / binary_name())
    candidates.append(Path(__file__).resolve().parents[2] / 'vendor' / 'gpt-load' / binary_name())
    for path in candidates:
        if path.is_file():
            return path
    return None


def read_version(binary):
    try:
        return json.loads((Path(binary).parent / 'VERSION').read_text(encoding='utf-8'))
    except (OSError, ValueError, TypeError):
        return {}


def pid_is_gateway(pid):
    """True only if `pid` is alive AND is a gpt-load process (so a recycled PID is never touched)."""
    try:
        if os.name == 'nt':
            out = subprocess.run(['tasklist', '/FI', f'PID eq {int(pid)}', '/FO', 'CSV', '/NH'], capture_output=True,
                                 text=True, timeout=10, creationflags=0x08000000).stdout.lower()
        else:
            out = subprocess.run(['ps', '-p', str(int(pid)), '-o', 'comm='], capture_output=True, text=True, timeout=10).stdout.lower()
        return 'gpt-load' in out
    except (OSError, ValueError, subprocess.SubprocessError):
        return False


def kill_pid(pid):
    try:
        if os.name == 'nt':
            subprocess.run(['taskkill', '/PID', str(int(pid)), '/T', '/F'], capture_output=True, timeout=15, creationflags=0x08000000)
        else:
            os.kill(int(pid), 15)
    except (OSError, ValueError, subprocess.SubprocessError):
        pass


def port_in_use(port):
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.settimeout(0.5)
        return sock.connect_ex(('127.0.0.1', port)) == 0


class GatewayManager:
    def __init__(self, settings, secrets, port=None, command=None, binary=None):
        self.settings = settings
        self.secrets = secrets
        self.port = int(port or os.environ.get('MAVOBOX_GATEWAY_PORT') or DEFAULT_PORT)
        self.command = command          # tests inject a fake gateway command
        self._binary = binary
        self.dir = Path(settings.data_dir) / 'gateway'
        self.proc = None
        self.adopted = False            # a healthy gateway was already listening: we reuse it
        self.adopted_pid = None         # ...and may stop it if the pid file proves it is our own leftover gpt-load
        self.lock = threading.RLock()

    # --- configuration -------------------------------------------------------------------------
    @property
    def binary(self):
        return self._binary or find_binary()

    def available(self):
        return bool(self.command) or self.binary is not None

    def _pid_path(self):
        return self.dir / 'gateway.pid'

    def _read_pid(self):
        try:
            return int(self._pid_path().read_text().strip())
        except (OSError, ValueError):
            return None

    def _settings_path(self):
        return self.dir / 'settings.json'

    def enabled(self):
        try:
            return bool(json.loads(self._settings_path().read_text(encoding='utf-8')).get('enabled'))
        except (OSError, ValueError):
            return False

    def _set_enabled(self, value):
        self.dir.mkdir(parents=True, exist_ok=True)
        self._settings_path().write_text(json.dumps({'enabled': bool(value)}), encoding='utf-8')

    def admin_key(self):
        key = self.secrets.get(ADMIN_SECRET_ID)
        if not key:
            key = pysecrets.token_urlsafe(24)
            self.secrets.set(ADMIN_SECRET_ID, key)
        return key

    # --- state ---------------------------------------------------------------------------------
    def healthy(self):
        try:
            response = httpx.get(f'http://127.0.0.1:{self.port}/health', timeout=1.5, follow_redirects=False)
            return response.status_code == 200
        except httpx.HTTPError:
            return False

    def owned_alive(self):
        return self.proc is not None and self.proc.poll() is None

    def status(self):
        version = read_version(self.binary) if self.binary else {}
        running = self.healthy()
        return dict(available=self.available(), enabled=self.enabled(), running=running,
                    managed=self.owned_alive(), port=self.port, url=f'http://127.0.0.1:{self.port}',
                    openai_base_url=f'http://127.0.0.1:{self.port}/v1',
                    version=version.get('tag'), source=version.get('source'),
                    log=str(self.dir / 'logs' / 'gpt-load.log'))

    # --- lifecycle -----------------------------------------------------------------------------
    def start(self, wait_seconds=40):
        with self.lock:
            if not self.available():
                raise GatewayError('这个安装包里没有内置网关程序，请重新下载最新的安装包')
            if self.owned_alive() and self.healthy():
                return
            if port_in_use(self.port):
                if self.healthy():
                    self.adopted = True       # an earlier instance of ours (or the user's own) is serving
                    pid = self._read_pid()
                    self.adopted_pid = pid if pid and pid_is_gateway(pid) else None   # only a leftover of ours is stoppable
                    return
                raise GatewayError(f'端口 {self.port} 已被其他程序占用，无法启动内置网关')
            (self.dir / 'logs').mkdir(parents=True, exist_ok=True)
            env = {k: v for k, v in os.environ.items()
                   if k not in ('DATABASE_DSN', 'AUTH_KEY', 'HOST', 'PORT', 'DATA_DIR', 'BIND_ADDRESS')}
            env.update(HOST='127.0.0.1', PORT=str(self.port), DATA_DIR=str(self.dir), AUTH_KEY=self.admin_key())
            command = self.command or [str(self.binary)]
            log = open(self.dir / 'logs' / 'gpt-load.log', 'ab')
            flags = 0x08000000 if os.name == 'nt' else 0   # CREATE_NO_WINDOW
            try:
                self.proc = subprocess.Popen(command, cwd=str(self.dir), env=env, stdin=subprocess.DEVNULL,
                                             stdout=log, stderr=subprocess.STDOUT, creationflags=flags)
            except OSError:
                raise GatewayError('无法启动内置网关程序（可能被杀毒软件拦截）') from None
            finally:
                log.close()
            self.adopted = False
            self.adopted_pid = None
            try:
                self._pid_path().write_text(str(self.proc.pid))
            except OSError:
                pass
            deadline = time.monotonic() + wait_seconds
            while time.monotonic() < deadline:
                if self.proc.poll() is not None:
                    raise GatewayError('内置网关启动后立即退出，请打开日志文件夹查看 gateway/logs/gpt-load.log')
                if self.healthy():
                    return
                time.sleep(0.4)
            self.stop()
            raise GatewayError('内置网关 40 秒内没有就绪')

    def stop(self):
        with self.lock:
            proc, self.proc = self.proc, None
            if proc and proc.poll() is None:
                proc.terminate()
                try:
                    proc.wait(timeout=6)
                except subprocess.TimeoutExpired:
                    proc.kill()
                    proc.wait(timeout=5)
            if self.adopted_pid:                  # a leftover gateway of ours from an earlier crash
                kill_pid(self.adopted_pid)
                deadline = time.monotonic() + 5
                while time.monotonic() < deadline and self.healthy():
                    time.sleep(0.2)
            self.adopted = False
            self.adopted_pid = None
            try:
                self._pid_path().unlink(missing_ok=True)
            except OSError:
                pass

    def set_enabled(self, value):
        self._set_enabled(value)
        if value:
            self.start()
        else:
            self.stop()

    def autostart(self):
        """Called when the backend starts: bring the gateway up only if the user enabled it."""
        if self.enabled() and self.available():
            try:
                self.start()
            except GatewayError:
                pass   # surfaced in the UI status; never blocks the app from starting

    def open_console(self):
        if not self.healthy():
            raise GatewayError('网关还没有运行')
        webbrowser.open(f'http://127.0.0.1:{self.port}')
